'use strict';
/* public/js/55-input.js -- keyboard/mouse/touch input (with the key-remap layer). Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- input ---------- */
const isTouch=('ontouchstart' in window)||navigator.maxTouchPoints>0;
function releaseLock(){if(document.pointerLockElement){voluntaryRelease=true;try{document.exitPointerLock()}catch(e){}}}
function lockOk(){return document.pointerLockElement===canvas}
canvas.addEventListener('mousedown',e=>{
  if(!S.started||uiOpen()||S.ko)return;
  if(!lockOk()&&!isTouch){try{const r=canvas.requestPointerLock();if(r&&r.catch)r.catch(()=>{})}catch(err){}}
  if(e.button===0&&lockOk())digHeld=true;
  dragLook={x:e.clientX,y:e.clientY};
});
addEventListener('mouseup',e=>{if(e.button===0)digHeld=false;dragLook=null});
let dragLook=null;
addEventListener('mousemove',e=>{
  if(!S.started)return;
  const iv=SETTINGS.invertY?-1:1;   // pause menu: sensitivity + invert-Y settings
  if(lockOk()){P.yaw-=e.movementX*0.0026*SETTINGS.sens;P.pitch=pc(P.pitch+e.movementY*0.0022*SETTINGS.sens*iv)}
  else if(dragLook&&!isTouch){P.yaw-=(e.clientX-dragLook.x)*0.005*SETTINGS.sens;P.pitch=pc(P.pitch+(e.clientY-dragLook.y)*0.004*SETTINGS.sens*iv);dragLook={x:e.clientX,y:e.clientY}}
});
document.addEventListener('pointerlockchange',()=>{
  if(!lockOk()){
    digHeld=false;
    if(voluntaryRelease)voluntaryRelease=false;   // we released it ourselves (shop/dialog/pause/etc): nothing more to do
    else if(S.started&&!overlayBlocking())openPause();   // browser dropped the lock on its own -- almost always Escape, which many browsers swallow instead of sending us a keydown
  }
});
const SHOUTS=['Hey, Caveman!','LIZARD! RUN!','I found something!','Dig over here!','Water truck!'];
addEventListener('keydown',e=>{
  const pk=e.key.toLowerCase();   // pause menu: the raw physical key, before any rebinding is applied
  if(e.target===conIn){conKey(e);return}
  if((e.key==='`'||e.key==='~')&&S.started&&!chatOpen()){e.preventDefault();openConsole();return}
  if(e.target===chatIn){if(e.key==='Enter'){e.preventDefault();sendChat()}else if(e.key==='Escape')closeChat();return}
  if(e.target&&e.target.tagName==='INPUT'){if(e.key==='Enter')startGame();return}
  if(!$('#fired').hidden)return;
  if(pk===SETTINGS.binds.chat&&S.started&&!uiOpen()){e.preventDefault();openChat();return}
  if(shopOpen){if(e.key==='Escape'||e.key==='f'||e.key==='F'){e.preventDefault();closeShop()}return}
  if(DLG.open){if(e.key==='Escape'){e.preventDefault();closeDialog()}else if(/^[1-9]$/.test(e.key)){e.preventDefault();chooseOpt(+e.key-1)}return}
  if(BJ.open){const k2=e.key.toLowerCase();if(k2==='escape'){e.preventDefault();closeCards()}else if(k2==='h')bjHit();else if(k2==='s')bjStand();else if(k2==='d')bjDouble();else if(k2==='enter'&&e.target.tagName!=='BUTTON')bjDeal();return}
  /* pause menu: Escape toggles it, after every menu above has had first crack at its own Escape handling.
     While it's open, every other key is swallowed here too (same pattern as the shop/dialog/blackjack blocks above). */
  if(pk==='escape'){e.preventDefault();if(PAUSE.open)closePause();else if(S.started&&!overlayBlocking())openPause();return}
  if(PAUSE.open)return;
  if(!S.started)return;
  if(pk.length===1){net.typed=(net.typed+pk).slice(-8);if(net.typed.endsWith('sploosh')){net.typed='';toggleAdmin()}if(net.typed.endsWith('disco')){net.typed='';if(net.ws&&net.ws.readyState===1)wsSend({t:'disco'});else startParty(net.id,S.name,60)}}
  const k=remapKey(pk);if(!k)return;   // pause menu: translate the physical key to the default key name the checks below expect
  KEYS[k]=true;
  if(k===' '||k.startsWith('arrow'))e.preventDefault();
  if(k==='e'){
    // E is normally hold-to-dig, but at a tent door/exit/bunk it enters/leaves/lies down instead (digging
    // is already blocked in camp, so this never steals a dig anywhere it would have worked).
    const s=nearSpot();
    if(s&&(s.id==='tentdoor'||s.id==='exit'||s.id==='bunk')){if(!e.repeat&&!S.ko&&!uiOpen())use()}
    else digHeld=true;
  }
  if(k==='f')use();
  if(k==='q')eatOnion();
  if(k==='g'&&!e.repeat)doPing();
  if(k==='l'&&!e.repeat)toggleLight();
  if(k==='v')toggleView();
  if(k==='c'){P.crouch=!P.crouch;toast(P.crouch?'Crouching. In a deep hole, the police can\'t see you.':'Standing up','',1600)}
  if(k==='m'){muted=!muted;if(master)master.gain.value=muted?0:SETTINGS.volMaster;toast(muted?'Sound off':'Sound on','',1200)}
  if(k==='b'&&!e.repeat&&VOX.enabled&&VOX.mode==='ptt')setMicTransmitting(true);
  if(k==='t'&&S.up.detector){S.detOn=!S.detOn;toast(S.detOn?'Detector on':'Detector off','',1200)}
  if(k>='1'&&k<='5')shout(+k-1);
});
addEventListener('keyup',e=>{const k=remapKey(e.key.toLowerCase());if(!k)return;KEYS[k]=false;if(k==='e')digHeld=false;if(k==='b'&&VOX.enabled&&VOX.mode==='ptt')setMicTransmitting(false)});
addEventListener('blur',()=>{for(const k in KEYS)KEYS[k]=false;digHeld=false;if(VOX.enabled&&VOX.mode==='ptt')setMicTransmitting(false)});
function shout(i){if(S.ko)return;say(meL,SHOUTS[i]);sfx.shout();S.noise=1;wsSend({t:'say',i})}
function eatOnion(){if(S.onions<=0){toast('No onions. The Wreck Room sells them for 8 seeds.','bad',2200);return}S.onions--;S.onionT=45;toast('You ate a raw onion. Lizards hate that smell. 45 seconds.','good');tone(220,0.3,'triangle',0.1,160)}

/* touch */
const touch={id:null,ox:0,oy:0,ix:0,iz:0,lookId:null,lx:0,ly:0};
if(isTouch){
  $('#touch').hidden=false;$('#keys').textContent='';
  canvas.addEventListener('touchstart',e=>{if(!S.started)return;for(const t of e.changedTouches){if(t.clientX<innerWidth*0.45&&touch.id===null){touch.id=t.identifier;touch.ox=t.clientX;touch.oy=t.clientY}else if(touch.lookId===null){touch.lookId=t.identifier;touch.lx=t.clientX;touch.ly=t.clientY}}e.preventDefault()},{passive:false});
  canvas.addEventListener('touchmove',e=>{for(const t of e.changedTouches){if(t.identifier===touch.id){const dx=clamp(t.clientX-touch.ox,-50,50),dy=clamp(t.clientY-touch.oy,-50,50);touch.ix=dx/50;touch.iz=-dy/50;$('#knob').style.transform=`translate(${dx}px,${dy}px)`}else if(t.identifier===touch.lookId){const iv=SETTINGS.invertY?-1:1;P.yaw-=(t.clientX-touch.lx)*0.006*SETTINGS.touchSens;P.pitch=pc(P.pitch+(t.clientY-touch.ly)*0.004*SETTINGS.touchSens*iv);touch.lx=t.clientX;touch.ly=t.clientY}}e.preventDefault()},{passive:false});
  const end=e=>{for(const t of e.changedTouches){if(t.identifier===touch.id){touch.id=null;touch.ix=touch.iz=0;$('#knob').style.transform=''}if(t.identifier===touch.lookId)touch.lookId=null}};
  canvas.addEventListener('touchend',end);canvas.addEventListener('touchcancel',end);
  const hold=(id,on,off)=>{const b=$(id);b.addEventListener('touchstart',e=>{e.preventDefault();on()},{passive:false});b.addEventListener('touchend',e=>{e.preventDefault();off&&off()},{passive:false})};
  hold('#tDig',()=>{digHeld=true},()=>{digHeld=false});
  hold('#tJump',()=>{KEYS[' ']=true},()=>{KEYS[' ']=false});
  hold('#tUse',()=>use());hold('#tOnion',()=>eatOnion());
  let si=0;hold('#tShout',()=>{shout(si);si=(si+1)%SHOUTS.length});
}

